import './NotificationList.css';

export interface Notification {
  id: string;
  message: string;
}

interface NotificationListProps {
  items: Notification[];
  isLoading: boolean;
}

export function NotificationList({ items, isLoading }: NotificationListProps): JSX.Element {
  if (isLoading) {
    return (
      <ul role="list" className="notification-list">
        {Array.from({ length: 4 }).map((_, i) => (
          <li key={i} className="notification-item notification-item--skeleton">
            <span className="notification-skeleton-bar" />
          </li>
        ))}
      </ul>
    );
  }

  return (
    <ul role="list" className="notification-list">
      {items.map((item) => (
        <li key={item.id} className="notification-item">
          {item.message}
        </li>
      ))}
    </ul>
  );
}

