import './DataTable.css';

export interface Row {
  id: string;
  cells: string[];
}

interface DataTableProps {
  rows: Row[];
  loading: boolean;
}

const SKELETON_COUNT = 5;
const SKELETON_CELL_COUNT = 3;

export function DataTable({ rows, loading }: DataTableProps): JSX.Element {
  return (
    <table role="table" className="data-table">
      <tbody>
        {loading
          ? Array.from({ length: SKELETON_COUNT }).map((_, i) => (
              <tr key={i} className="data-table-row data-table-row--skeleton">
                {Array.from({ length: SKELETON_CELL_COUNT }).map((__, j) => (
                  <td key={j} className="data-table-cell">
                    <span className="data-table-shimmer" />
                  </td>
                ))}
              </tr>
            ))
          : rows.map((row) => (
              <tr key={row.id} className="data-table-row">
                {row.cells.map((cell, j) => (
                  <td key={j} className="data-table-cell">
                    {cell}
                  </td>
                ))}
              </tr>
            ))}
      </tbody>
    </table>
  );
}

