import { useState } from 'react';
import './ChipBar.css';

// Owns only visual pressed state; grid filtering is not wired.

interface ChipBarProps {
  statuses: string[];
}

export function ChipBar({ statuses }: ChipBarProps): JSX.Element {
  const [pressed, setPressed] = useState<Set<string>>(new Set());

  function handleClick(status: string): void {
    const updated = new Set(pressed);
    if (updated.has(status)) {
      updated.delete(status);
    } else {
      updated.add(status);
    }
    setPressed(updated);
  }

  return (
    <div className="chip-bar" role="group">
      {statuses.map((status) => (
        <button
          key={status}
          className="chip-bar-chip"
          aria-pressed={pressed.has(status)}
          onClick={() => handleClick(status)}
        >
          {status}
        </button>
      ))}
    </div>
  );
}

